var t=`0423-r-dgr-d-med-fl-de`;var i=`world-0423`;var n=`DK`;var a=`northern-europe`;var o=4;var d=138;var s={en:`Rødgrød med Fløde`,ua:`Ягідний кисіль із вершками`};var h={en:`A traditional dish from Denmark, centered on raspberry, redcurrant, potato starch, heavy cream. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Данія. Основні складники: малина, червона смородина, картопляний крохмаль, вершки високої жирності. Домашній варіант із кількостями продуктів за етапами приготування.`};var m=[{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 12 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 12 хвилин до м’якості та готовності.`,t:[`simmering`],m:12,i:[[`raspberry`,350,`g`],[`redcurrant`,280,`g`],[`white-granulated-sugar`,140,`g`],[`water`,250,`ml`]]},{en:`Whisk starch with cold water, pour into the hot berry mixture and briefly bring back to a simmer until glossy and thickened, then cool.`,ua:`Збийте крохмаль із холодною водою, влийте до гарячих ягід, коротко доведіть до слабкого кипіння до блиску й загустіння, потім охолодіть.`,t:[`mixing`],m:4,i:[[`potato-starch`,35,`g`],[`water`,80,`ml`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 120 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 120 хвилин.`,t:[`rapid-chilling`],m:120,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`heavy-cream`,230,`ml`]]}];var g={slug:t,id:i,country:`DK`,region:a,servings:4,minutes:138,title:s,text:h,steps:m};export{n as country,g as default,i as id,d as minutes,a as region,o as servings,t as slug,m as steps,h as text,s as title};